    async def list_key_rotations_all(
        self,
        *,
        key_id: str,
        region: str | None = None,
        order_by: ListKeyRotationsRequestOrderBy | None = None,
        page_size: int | None = None,
        status: list[KeyRotationStatus] | None = None,
    ) -> list[KeyRotation]:
        """Every item of `list_key_rotations`, all pages read."""
        return [
            entry
            async for entry in self.list_key_rotations_iter(
                key_id=key_id,
                region=region,
                order_by=order_by,
                page_size=page_size,
                status=status,
            )
        ]

    async def sign(
        self,
        *,
        key_id: str,
        region: str | None = None,
        digest: str | None = None,
        msg: str | None = None,
        external_mu: str | None = None,
    ) -> SignResponse:
        """
        Sign a message digest

        Use a given key to sign a message digest. The key must have its usage set to
        `asymmetric_signing`. The digest must be created using the same digest algorithm
        that is defined in the key's algorithm configuration.

        Args:
            region: The region you want to target
            key_id: ID of the key to use for signing. (UUID format)
            digest: Pre-hashed digest of the message to sign. For ECDSA and RSA keys,
                the digest generated using the key's hashing algorithm: 32 bytes
                (SHA-256) or 48 bytes (SHA-384). The 64-byte bound only exists for the
                ML-DSA backward-compatibility case below. Also accepted for ML-DSA for
                backward compatibility only; signatures may not conform to the ML-DSA
                spec, not recommended for new usage. Prefer `message` or `external_mu`
                for ML-DSA. One of digest, msg, external_mu is required.
            msg: Full message to sign as-is. Only supported for ML-DSA keys (`raw`
                signing): the server computes the μ message representative internally
                before signing. Between 1 and 4096 bytes. One of digest, msg,
                external_mu is required.
            external_mu: ML-DSA pre-hashed μ message representative, exactly 64 bytes.
                Must equal SHAKE256(tr ‖ 0x00 ‖ 0x00 ‖ message), where `tr` is the
                SHAKE256 of the key's public key. Signatures produced from other pre-
                hash computations (e.g. HashML-DSA) cannot be verified through this API.
                One of digest, msg, external_mu is required.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/key-manager/v1alpha1/regions/{region}/keys/{key_id}/sign",
                region=self._client.region(region),
                key_id=key_id,
            ),
            body={"digest": digest, "msg": msg, "external_mu": external_mu},
        )
        return SignResponse.model_validate(data)

    async def unprotect_key(
        self,
        *,
        key_id: str,
        region: str | None = None,
    ) -> Key:
        """
        Remove key protection

        Remove key protection from a given key specified by the `key_id` parameter.
        Removing key protection means that your key can be deleted anytime.

        Args:
            region: The region you want to target
            key_id: ID of the key to remove key protection from. (UUID format)
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/key-manager/v1alpha1/regions/{region}/keys/{key_id}/unprotect",
                region=self._client.region(region),
                key_id=key_id,
            ),
            body={},
        )
        return Key.model_validate(data)

    async def unwrap_key(
        self,
        *,
        key_id: str,
        region: str | None = None,
        ciphertext: str | None = None,
        associated_data: BytesValue | None = None,
    ) -> UnwrapKeyResponse:
        """
        Unwrap a key

        Unwrap (decrypt) a wrapped key using an existing key, specified by the `key_id`
        parameter. The key must use ML-KEM algorithm. The maximum key size that can be
        unwrapped is 4 KB of ciphertext.

        Args:
            region: The region you want to target
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/key-manager/v1alpha1/regions/{region}/keys/{key_id}/unwrap",
                region=self._client.region(region),
                key_id=key_id,
            ),
            body={"ciphertext": ciphertext, "associated_data": associated_data},
        )
        return UnwrapKeyResponse.model_validate(data)

    async def verify(
        self,
        *,
        key_id: str,
        region: str | None = None,
        digest: str | None = None,
        msg: str | None = None,
        signature: str | None = None,
    ) -> VerifyResponse:
        """
        Verify a message signature

        Use a given key to verify a message signature against a message digest. The key
        must have its usage set to `asymmetric_signing`. The message digest must be
        generated using the same digest algorithm that is defined in the key's algorithm
        configuration.

        Args:
            region: The region you want to target
            key_id: ID of the key to use for signature verification. (UUID format)
            digest: Digest that was signed. For ECDSA and RSA keys, the digest of the
                original message, generated using the key's hashing algorithm. One of
                digest, msg is required.
            msg: Message that was signed. For ML-DSA keys, the full original message.
                This also verifies signatures made with `raw` or `external_mu`: send the
                message whose μ was signed, not the μ itself (a μ payload always fails).
                Messages over 4096 bytes cannot be verified through this endpoint. One
                of digest, msg is required.
            signature: The message signature to verify.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/key-manager/v1alpha1/regions/{region}/keys/{key_id}/verify",
                region=self._client.region(region),
                key_id=key_id,
            ),
            body={"digest": digest, "msg": msg, "signature": signature},
        )
        return VerifyResponse.model_validate(data)

    async def wrap_key(
        self,
        *,
        key_id: str,
        region: str | None = None,
        plaintext: str | None = None,
        associated_data: BytesValue | None = None,
    ) -> WrapKeyResponse:
        """
        Wrap a key

        Wrap (encrypt) a key using an existing key, specified by the `key_id` parameter.
        The key must use ML-KEM algorithm. The maximum key size that can be wrapped is 2
        KB of plaintext.

        Args:
            region: The region you want to target
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/key-manager/v1alpha1/regions/{region}/keys/{key_id}/wrap",
                region=self._client.region(region),
                key_id=key_id,
            ),
            body={"plaintext": plaintext, "associated_data": associated_data},
        )
        return WrapKeyResponse.model_validate(data)
